package net.civeira.phylax.features.document.templatevariable.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.templatevariable.application.visibility.TemplateVariableFixedPropertiesProposal;

public class FixTenantExcludingRoot {

  /**
   * Constant for platformGlobalAccess scope
   *
   * @autogenerated VisibilityPolicyGenerator
   */
  private static final String SCOPE_PLATFORM_GLOBAL_ACCESS = "platform:global_access";

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param fixed
   */
  public void fixedFields(@Observes TemplateVariableFixedPropertiesProposal fixed) {
    Actor actor = fixed.getActor();
    if (!actor.hasScope(SCOPE_PLATFORM_GLOBAL_ACCESS)) {
      fixed.add("tenant");
    }
  }
}
